import {
  OTP_LOCKOUTS_COLLECTION_NAME,
  db,
  isDuplicateKeyError
} from '~/src/mongo.js'

/**
 * @typedef {object} OtpLockoutDocument
 * @property {unknown} _id - generated by Mongo
 * @property {string} target - lowercased email the codes were requested for
 * @property {Date} windowStartedAt - when the current count started
 * @property {number} requests - codes requested since the window started
 * @property {Date | null} lockedUntil - when the address may request again; null while it is not locked out
 * @property {Date} createdAt - when the counter was first minted
 * @property {Date} expireAt - checked in-app; Mongo TTL is GC only
 */

/**
 * @param {Filter<OtpLockoutDocument>} filter
 */
export function findOne(filter) {
  return coll().findOne(filter)
}

/**
 * Applies fields to the matching counter. The boolean return is the atomic
 * claim signal: false means the filter no longer matched, i.e. a concurrent
 * request already moved the counter on.
 * @param {Filter<OtpLockoutDocument>} filter
 * @param {MatchKeysAndValues<OtpLockoutDocument>} fields
 * @returns {Promise<boolean>} whether a counter matched
 */
export async function update(filter, fields) {
  const { matchedCount } = await coll().updateOne(filter, { $set: fields })
  return matchedCount > 0
}

/**
 * Removes the counter for an address, so its next request starts a fresh
 * count. Matching nothing is success: the address had no counter to clear.
 * @param {Filter<OtpLockoutDocument>} filter
 */
export async function clear(filter) {
  await coll().deleteOne(filter)
}

/**
 * Counts one code request against the counter for a key, minting the
 * counter when the address has never asked for a code, and returns the
 * counter as it now stands. The increment is atomic, so concurrent requests
 * each get their own number and none of them share one.
 * @param {{ target: string }} key
 * @param {MatchKeysAndValues<OtpLockoutDocument>} fields - applied on every request
 * @param {MatchKeysAndValues<OtpLockoutDocument>} onInsert - applied only when the counter is minted
 * @returns {Promise<OtpLockoutDocument>}
 */
export async function incrementRequests(key, fields, onInsert) {
  const updateRequest = {
    $inc: { requests: 1 },
    $set: fields,
    $setOnInsert: { ...onInsert, createdAt: new Date() }
  }

  try {
    const doc = await coll().findOneAndUpdate(key, updateRequest, {
      upsert: true,
      returnDocument: 'after'
    })

    // upsert with returnDocument 'after' always yields a document
    return /** @type {OtpLockoutDocument} */ (doc)
  } catch (err) {
    if (!isDuplicateKeyError(err)) {
      throw err
    }

    // Two first requests for an address in flight together both take the
    // insert path, and the unique index rejects the loser. The winner's
    // counter now exists, so the same call is an increment second time
    // round: retry once rather than fail a request that should be counted.
    const doc = await coll().findOneAndUpdate(key, updateRequest, {
      returnDocument: 'after'
    })

    return /** @type {OtpLockoutDocument} */ (doc)
  }
}

/**
 * The otp lockouts collection (resolved lazily — the `db` live binding is
 * only assigned once `prepareDb` has run)
 * @returns {Collection<OtpLockoutDocument>}
 */
function coll() {
  return /** @type {Collection<OtpLockoutDocument>} */ (
    db.collection(OTP_LOCKOUTS_COLLECTION_NAME)
  )
}

/**
 * @import { Collection, Filter, MatchKeysAndValues } from 'mongodb'
 */
